  // Close every stray tab pointed at the app so no other connection can block deleteDatabase.
  const existing = await browser.pages();
  for (const p of existing) {
    if (p.url().includes('127.0.0.1:5173')) await p.close();
  }

  const page = await browser.newPage();
  await page.setViewport({ width: 1280, height: 800 });

  page.on('console', (msg) => {
    consoleMessages.push({ type: msg.type(), text: msg.text(), location: msg.location() });
  });
  page.on('pageerror', (err) => {
    consoleMessages.push({ type: 'pageerror', text: String(err) });
  });
  page.on('requestfailed', (req) => {
    failedRequests.push({ url: req.url(), failure: req.failure() && req.failure().errorText, method: req.method() });
  });
  page.on('response', (res) => {
    if (res.status() >= 400) {
      failedRequests.push({ url: res.url(), status: res.status(), method: res.request().method() });
    }
  });

  // Fresh page, no prior connection open: safe to wipe the database for a clean slate.
  await page.goto(URL, { waitUntil: 'networkidle0', timeout: 20000 });
  await page.evaluate(async () => {
    const dbs = indexedDB.databases ? await indexedDB.databases() : [{ name: 'stallion' }];
    for (const d of dbs) {
      await new Promise((resolve) => {
        const req = indexedDB.deleteDatabase(d.name);
        req.onsuccess = () => resolve();
        req.onerror = () => resolve();
        req.onblocked = () => resolve();
      });
    }
  });
  await page.reload({ waitUntil: 'networkidle0', timeout: 20000 });
  await new Promise(r => setTimeout(r, 500));

  // Step 1: open page, note toolbar
  const toolbarInfo = await page.evaluate(() => {
    const colours = document.querySelectorAll('.tool.swatch').length;
    const sizes = document.querySelectorAll('.tool[aria-label$="pencil"]').length;
    return { colours, sizes };
  });
  fs.writeFileSync(path.join(DIR, 'toolbar-info.json'), JSON.stringify(toolbarInfo, null, 2));
  await shot(page, '01-initial-toolbar.png');

  // Step 2: draw two strokes, different colours and sizes
  await page.click('[aria-label="Colour 2"]');
  await page.click('[aria-label="Small pencil"]');
  await drawStroke(page, [
    { x: 300, y: 300 }, { x: 340, y: 260 }, { x: 380, y: 320 }, { x: 420, y: 260 }, { x: 460, y: 320 },
  ]);

  await page.click('[aria-label="Colour 4"]');
  await page.click('[aria-label="Large pencil"]');
  await drawStroke(page, [
    { x: 700, y: 500 }, { x: 740, y: 460 }, { x: 780, y: 520 }, { x: 820, y: 460 }, { x: 860, y: 520 },
  ]);
  await new Promise(r => setTimeout(r, 250));
  await shot(page, '02-two-strokes.png');

  // Step 3: zoom OUT several steps (verified: positive deltaY = zoom out), then draw one large stroke
  await wheelSteps(page, 580, 390, 130, 6);
  await new Promise(r => setTimeout(r, 250));
  await shot(page, '03a-zoomed-out-before-stroke.png');
  await page.click('[aria-label="Colour 5"]');
  await page.click('[aria-label="Medium pencil"]');
  await drawStroke(page, [
    { x: 150, y: 200 }, { x: 350, y: 150 }, { x: 550, y: 250 }, { x: 750, y: 150 }, { x: 950, y: 250 },
  ]);
  await new Promise(r => setTimeout(r, 250));
  await shot(page, '03-zoomed-out-large-stroke.png');

  // Step 4: zoom IN past the original zoom level (anchored near the first strokes), draw a small stroke between them
  await wheelSteps(page, 580, 390, -130, 13);
  await new Promise(r => setTimeout(r, 250));
  await shot(page, '04a-zoomed-in-before-stroke.png');
  await page.click('[aria-label="Colour 6"]');
  await page.click('[aria-label="Small pencil"]');
  await drawStroke(page, [
    { x: 600, y: 450 }, { x: 615, y: 440 }, { x: 630, y: 455 }, { x: 645, y: 440 },
  ]);
  await new Promise(r => setTimeout(r, 250));
  await shot(page, '04-zoomed-in-small-stroke.png');

  // Step 5: zoom out far enough that the small stroke should be culled below one pixel
  await wheelSteps(page, 580, 390, 130, 26);
  await new Promise(r => setTimeout(r, 300));
  await shot(page, '05-zoomed-out-culled.png');

  // Step 6: reload, confirm strokes reappear
  await page.reload({ waitUntil: 'networkidle0', timeout: 20000 });
  await new Promise(r => setTimeout(r, 600));
  await shot(page, '06-after-reload.png');

  // Step 7: pan via middle mouse button drag over canvas, screenshot
  const canvasBox = await page.evaluate(() => {
    const c = document.querySelector('canvas.surface');
    const r = c.getBoundingClientRect();
    return { x: r.x, y: r.y, width: r.width, height: r.height };
  });
  const cx = canvasBox.x + canvasBox.width / 2;
  const cy = canvasBox.y + canvasBox.height / 2;
  await page.mouse.move(cx, cy);
  await page.mouse.down({ button: 'middle' });
  await page.mouse.move(cx - 80, cy - 60, { steps: 10 });
  await page.mouse.move(cx - 140, cy - 100, { steps: 10 });
  await page.mouse.up({ button: 'middle' });
  await new Promise(r => setTimeout(r, 300));
  await shot(page, '07-panned.png');

  // IndexedDB summary
  const idbSummary = await page.evaluate(async () => {
    const dbsFn = indexedDB.databases ? indexedDB.databases.bind(indexedDB) : null;
    const dbList = dbsFn ? await dbsFn() : [];
    const results = [];
    for (const dbInfo of dbList) {
      const dbName = dbInfo.name;
      const req = indexedDB.open(dbName);
      const db = await new Promise((resolve, reject) => {
        req.onsuccess = () => resolve(req.result);
        req.onerror = () => reject(req.error);
      });
      const storeNames = Array.from(db.objectStoreNames);
      const storeCounts = {};
      for (const sn of storeNames) {
        const tx = db.transaction(sn, 'readonly');
        const store = tx.objectStore(sn);
        const count = await new Promise((resolve, reject) => {
          const r = store.count();
          r.onsuccess = () => resolve(r.result);
          r.onerror = () => reject(r.error);
        });
        storeCounts[sn] = count;
      }
      db.close();
      results.push({ name: dbName, version: dbInfo.version, stores: storeCounts });
    }
    return results;
  });

  fs.writeFileSync(path.join(DIR, 'indexeddb-summary.json'), JSON.stringify(idbSummary, null, 2));
  fs.writeFileSync(path.join(DIR, 'console-messages.json'), JSON.stringify(consoleMessages, null, 2));
  fs.writeFileSync(path.join(DIR, 'failed-requests.json'), JSON.stringify(failedRequests, null, 2));

  console.log('DONE');
  console.log('toolbarInfo', JSON.stringify(toolbarInfo));
  console.log('consoleErrorCount', consoleMessages.filter(m => m.type === 'error' || m.type === 'pageerror').length);
  console.log('failedRequestCount', failedRequests.length);
  console.log('idbSummary', JSON.stringify(idbSummary));

  await browser.disconnect();
})().catch(e => {
  console.error('SCRIPT_ERROR', e);
  process.exit(1);
});

