  console.log('toolbarInfo', JSON.stringify(toolbarInfo));
  console.log('consoleErrorCount', consoleMessages.filter(m => m.type === 'error' || m.type === 'pageerror').length);
  console.log('failedRequestCount', failedRequests.length);
